/**
 * 负责角色查验本夜提交和可选完成回执。输入为原 World、实际夜晚、石像鬼／查验完成选择；
 * 输出为每夜记账及已完成目标知识，不创建活跃能力或第二查验资源。状态族检查同 payload
 * 引用和政策；此 owner 仍在原顺序检查角色、生命版本、id、来源、激活、禁用及阶段当前性，
 * 替换或过期后不借合法 payload 恢复原回执。
 */
import { roleInspectionPolicy } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import type { GargoyleReadState as GargoyleState } from "@ai-werewolf-arena/game-contract";

import type { RoleInspectionReadState } from "@ai-werewolf-arena/game-contract";

import { aliveLifeVersion, type AliveComponent } from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Role } from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import { findNightAbility, type NightAbilityReadView } from "../abilities";
import { getGargoyleState } from "../gargoyle/ports";

import { ROLE_INSPECTION_STATE_SLOT } from "./state-slot";

interface Completion {
  actorId: number;
  role: RoleComponent;
  privateState: RoleComponent["privateState"];
  state: GargoyleState;
  ability: NightAbilityReadView<"role_check">;
  abilityId: string;
  activation: NightAbilityReadView["activation"];
  inspection: RoleInspectionReadState;
  inspectionPolicy: RoleInspectionReadState["inspectionPolicy"];
  life: AliveComponent;
  version: number;
  isCurrent: () => boolean;
}
const nights = new WeakMap<World, { day: number; completed: Map<RoleComponent, Completion> }>();
const committed = new WeakMap<World, Set<number>>();
export function hasRoleInspectionNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}
export function beginRoleInspectionNight(world: World, day: number): void {
  if (nights.get(world)?.day !== day) nights.set(world, { day, completed: new Map() });
}
export function recordRoleInspectionNightCommit(
  world: World,
  day: number,
  isCurrent: () => boolean,
): void {
  if (!isCurrent()) return;
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}
export function recordRoleInspectionCompletion(
  world: World,
  actorId: number,
  day: number,
  ability: NightAbilityReadView<"role_check">,
  isCurrent: () => boolean,
): void {
  if (!isCurrent()) return;
  recordRoleInspectionNightCommit(world, day, isCurrent);
  const role = world.getComponent(actorId, COMPONENT.Role),
    state = role && getGargoyleState(role),
    life = world.getComponent(actorId, COMPONENT.Alive),
    version = life && aliveLifeVersion(life);
  if (
    roleInspectionPolicy(ability.state) !== "gargoyle" ||
    role?.role !== Role.Gargoyle ||
    !state ||
    !life?.alive ||
    version === undefined ||
    ability.source.kind !== "native" ||
    ability.source.role !== Role.Gargoyle
  )
    return;
  beginRoleInspectionNight(world, day);
  nights.get(world)!.completed.set(role, {
    actorId,
    role,
    privateState: role.privateState,
    state,
    ability,
    abilityId: ability.id,
    activation: ability.activation,
    inspection: ability.state,
    inspectionPolicy: ability.state.inspectionPolicy,
    life,
    version,
    isCurrent,
  });
}
export function completedGargoyleInspection(world: World, role: RoleComponent): boolean {
  const scope = nights.get(world)?.completed.get(role);
  if (
    !scope ||
    !scope.isCurrent() ||
    role.privateState !== scope.privateState ||
    getGargoyleState(role) !== scope.state ||
    role.role !== Role.Gargoyle ||
    scope.ability.id !== scope.abilityId ||
    scope.ability.activation !== scope.activation ||
    findNightAbility(role, "role_check", scope.abilityId) !== scope.ability ||
    scope.ability.source.kind !== "native" ||
    scope.ability.source.role !== Role.Gargoyle ||
    scope.ability.disabled ||
    ROLE_INSPECTION_STATE_SLOT.invalidations.payloadChanged(scope)
  )
    return false;
  return (
    world.getComponent(scope.actorId, COMPONENT.Role) === role &&
    world.getComponent(scope.actorId, COMPONENT.Alive) === scope.life &&
    scope.life.alive &&
    aliveLifeVersion(scope.life) === scope.version
  );
}

/**
 * Captures Awakened Hidden Wolf owner, mimic skill and mirror scopes for one real night. Inputs
 * are the original ability and role/life references; outputs are currentness checks and
 * night-commit bookkeeping. It never lets a new state, source or body inherit the old captured
 * permission.
 */
import type {
  AwakenedReadState as AwakenedState,
  AwakenedReadActiveSkill as AwakenedActiveSkill,
} from "@ai-werewolf-arena/game-contract";

import { aliveLifeVersion } from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, type EntityId } from "../../../../core/domain/model";
import {
  captureNightLife,
  livingNightLife,
  type NightLifeScope,
} from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import { awakenedSkillForNight, getAwakenedState } from "./state";
import { findNightAbility, type NightAbilityReadView } from "../abilities";

export interface AwakenedOwnerScope {
  readonly world: World;
  readonly actorId: EntityId;
  readonly role: RoleComponent;
  readonly state: AwakenedState;
  readonly life: NightLifeScope;
  isCurrent(allowFirstDeath?: boolean): boolean;
}
export function captureAwakenedOwner(
  world: World,
  actorId: EntityId,
  phaseCurrent: () => boolean,
): AwakenedOwnerScope | null {
  const role = world.getComponent(actorId, COMPONENT.Role),
    state = getAwakenedState(role),
    life = captureNightLife(world, actorId);
  if (
    !phaseCurrent() ||
    !role ||
    role.role !== Role.AwakenedHiddenWolf ||
    role.camp !== Camp.Wolf ||
    !state ||
    !life
  )
    return null;
  const privateState = role.privateState;
  return {
    world,
    actorId,
    role,
    state,
    life,
    isCurrent: (allowFirstDeath = false) => {
      const original =
        world.getComponent(actorId, COMPONENT.Alive) === life.life &&
        aliveLifeVersion(life.life) ===
          life.version + (allowFirstDeath && !life.life.alive ? 1 : 0);
      return (
        phaseCurrent() &&
        world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.AwakenedHiddenWolf &&
        role.camp === Camp.Wolf &&
        role.privateState === privateState &&
        getAwakenedState(role) === state &&
        original &&
        (allowFirstDeath || life.life.alive)
      );
    },
  };
}
/** Bind paid facts without reading a closed slot or spent bottle/knife. */
export function bindAwakenedSkill(
  owner: AwakenedOwnerScope,
  day: number,
): { readonly skill: AwakenedActiveSkill; isCurrent(allowFirstDeath?: boolean): boolean } | null {
  const learned = owner.state.learned,
    skill = awakenedSkillForNight(owner.state, day);
  if (
    !owner.isCurrent() ||
    !learned ||
    !skill ||
    learned.activationNight === null ||
    learned.activeFromNight === null
  )
    return null;
  const { targetId, role, day: learnedDay, activationNight, activeFromNight } = learned,
    kind = skill.kind;
  return {
    skill,
    isCurrent: (allowFirstDeath = false) =>
      owner.isCurrent(allowFirstDeath) &&
      owner.state.learned === learned &&
      learned.skill === skill &&
      skill.kind === kind &&
      learned.targetId === targetId &&
      learned.role === role &&
      learned.day === learnedDay &&
      learned.activationNight === activationNight &&
      learned.activeFromNight === activeFromNight,
  };
}
/** Only the Aw-owned native Mirror depends on its learning; independent gifts/copies do not. */
export function captureAwakenedMirrorScope(
  world: World,
  actorId: EntityId,
  ability: NightAbilityReadView<"role_check">,
  day: number,
  phaseCurrent: () => boolean,
): (() => boolean) | null {
  const owner = captureAwakenedOwner(world, actorId, phaseCurrent),
    learned = owner?.state.learned,
    skill = learned?.skill;
  if (
    !owner ||
    currentAwakenedNight(world, owner.role) !== day ||
    !learned ||
    learned.role !== Role.MirrorGirl ||
    learned.activationNight === null ||
    learned.activeFromNight === null ||
    day < learned.activeFromNight ||
    skill?.kind !== "inspection" ||
    skill.abilityId !== ability.id
  )
    return null;
  const { targetId, role, day: learnedDay, activationNight, activeFromNight } = learned,
    abilityId = skill.abilityId;
  return () =>
    owner.isCurrent() &&
    currentAwakenedNight(world, owner.role) === day &&
    owner.state.learned === learned &&
    learned.skill === skill &&
    skill.kind === "inspection" &&
    skill.abilityId === abilityId &&
    learned.targetId === targetId &&
    learned.role === role &&
    learned.day === learnedDay &&
    learned.activationNight === activationNight &&
    learned.activeFromNight === activeFromNight &&
    findNightAbility(owner.role, "role_check", abilityId) === ability;
}
const nights = new WeakMap<
  World,
  { day: number; owners: Map<RoleComponent, AwakenedOwnerScope> }
>();
const committed = new WeakMap<World, Set<number>>();
export function beginAwakenedNight(
  world: World,
  day: number,
  owners: readonly AwakenedOwnerScope[],
): void {
  if (hasAwakenedNightCommit(world, day)) throw new Error("awakened_night_reentry_after_commit");
  if (nights.get(world)?.day === day) throw new Error("awakened_night_reentry_after_commit");
  if ((nights.get(world)?.day ?? day) > day) throw new Error("awakened_night_clock_regressed");
  const currentOwners = owners.filter((owner) => owner.world === world && owner.isCurrent());
  nights.set(world, { day, owners: new Map(currentOwners.map((owner) => [owner.role, owner])) });
  // Establishing this night's original-body authority is itself a committed prefix,
  // including nights with only an inherited base knife or no copied active skill.
  if (currentOwners.length) recordAwakenedNightCommit(world, day);
}
export function currentAwakenedNight(world: World, role: RoleComponent): number | null {
  const night = nights.get(world),
    owner = night?.owners.get(role);
  return night && owner?.isCurrent() && livingNightLife(world, owner.life) ? night.day : null;
}
export function recordAwakenedNightCommit(world: World, day: number): void {
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}
export function hasAwakenedNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}

/**
 * Captures inspection target identity and commits sourced Fox inspection claims. Inputs are
 * original target life/role references and owner-current checks; outputs preserve inspection
 * bookkeeping and delayed lethal claims. Knowledge publication does not itself mark the Fox
 * dead.
 */
import { COMPONENT, Role, Camp, type RoleComponent, type World } from "../../../../core/domain";
import { livingNightLife, type NightLifeScope } from "../../../../core/domain/night_effects";
import type { NightStageState } from "../../stages/night/contracts";
const committed = new WeakMap<World, Set<number>>();
export function hasFoxInspectionNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}
/** Snapshot before await; a new identity cannot acquire an old pending inspection. */
export function captureInspectionIdentity(world: World, target: NightLifeScope) {
  const role = world.getComponent(target.id, COMPONENT.Role);
  const kind = role?.role,
    camp = role?.camp,
    state = role?.privateState;
  return {
    role,
    isCurrent: () =>
      livingNightLife(world, target) &&
      world.getComponent(target.id, COMPONENT.Role) === role &&
      role?.role === kind &&
      role?.camp === camp &&
      role?.privateState === state,
  };
}
/** Only committed Seer-kind actions call this; read-only and role inspection never do. */
export function commitFoxInspection(
  world: World,
  state: NightStageState,
  target: NightLifeScope,
  day: number,
  ownerCurrent: () => boolean,
): void {
  const identity = captureInspectionIdentity(world, target);
  if (identity.role?.role !== Role.CursedFox || identity.role.camp !== Camp.ThirdParty) return;
  (state.foxInspections ??= []).push({
    target,
    isTargetCurrent: identity.isCurrent,
    isCurrent: () => ownerCurrent() && identity.isCurrent(),
  });
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}

/**
 * 单元测试：验证配置的查验／死亡政策在有界阶段、hook、校验、提示与投影中的实际使用。输入为角色／政策／语言矩阵和原 live 槽修改；手写许可、库存／历史计数和错误为预期。死亡链在场景中，此处不运行完整阶段或模型。
 */
import { rolePresentationRenderer } from "../../../src/game/observation/role-presentation";
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../src/app/bootstrap";
import {
  COMPONENT,
  DeathCause,
  Phase,
  Role,
  permitsDeathShot,
  type BoardConfig,
  type ActionRequest,
  type GameEvent,
  type RoleComponent,
  type DeathActionPolicy,
  type InspectionPolicy,
} from "../../../src/core";
import { sixPlayerMvpConfig } from "../../../src/runtime/scenarios/six_player_mvp";
import {
  boardDefinitionFromConfig,
  parseBoardDefinition,
} from "../../../src/runtime/config/board_definition";
import { boardConfigSchema } from "../../../src/core/domain/board_schema";
import { getDefaultRoleCatalog } from "../../../src/game/mechanisms/roles/role-catalog-assembly";
import {
  findNightAbility,
} from "../../../src/game/mechanisms/roles/abilities";
import { projectNightAbility } from "../../../src/game/observation/night-ability-projection";
import {
  grantNightAbility,
  transferNightAbility,
} from "../../../src/game/mechanisms/roles/night-ability-grants";
import {
  ROLE_INSPECTION_STAGE,
  PSYCHIC_INSPECTION_STAGE,
  MIRROR_INSPECTION_STAGE,
} from "../../../src/game/mechanisms/roles/role_inspection/contribution-ports";
import { roleInspectionTargets } from "../../../src/game/mechanisms/roles/role_inspection/contribution-ports";
import { getHunterState } from "../../../src/game/mechanisms/roles/hunter/ports";
