function fixture(day: number, locale: "zh-CN" | "en") {
  const { world } = bootstrapGame(structuredClone(pureWhiteTwelveConfig), { locale });
  const id = (role: Role) =>
    world
      .entityIds()
      .find((id) => world.getComponent(id, COMPONENT.Role)?.role === role)!;
  const pure = id(Role.PureWhiteGirl),
    wolf = id(Role.WolfWitch);
  let calls = 0;
  const ctx: NightStageContext = {
    world,
    get nightActors() {
      return bindNightAbilityActorQuery(this.world);
    },
    get nativeNightFailure() {
      return bindNativeNightFailurePolicy(() => this.world);
    },
    get nativeNightTargets() {
      return bindNativeNightTargetPolicy(() => this);
    },
    get nativeNightEffects() {
      return bindNativeNightEffects(() => this);
    },
    roleCatalog: getDefaultRoleCatalog(),
    toolGateway: new ToolGateway(),
    events: [],
    previousExile: null,
    isCurrent: () => true,
    currentDay: () => day,
    get requestFactory() { return GameActionRequestFactory; },
    actionProvider: {
      getAction: async (r) => {
        calls++;
        return {
          name: "inspect_night_identity",
          args: { target_id: r.actorId === pure ? wolf : pure, abstain: false },
        };
      },
    },
    makeRequest: (actorId, allowedTools, extras) => ({
      actorId,
